import React, { useRef } from 'react';
import { useIntl } from 'react-intl';

import { PanHorizontalIcon } from '@dynatrace/strato-icons';

import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { isPan } from '../../../core/functions/toolbarEvents.js';
import { useA11yToolbarTabIndex } from '../../../core/hooks/useA11yToolbarTabIndex.js';
import { useButtonKeyboardFocus } from '../../../core/hooks/useButtonKeyboardFocus.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { useToolbarEvent } from '../../../core/hooks/useToolbarEvent.js';
import {
  useCurrentDomainState,
  useSetState,
  useZoomState,
} from '../../hooks/store/selectors.js';
import { useHistogramInteractions } from '../../hooks/useHistogramInteractions.js';
import { HISTOGRAM_MESSAGES } from '../../messages/tooltip-text.js';

export const PanButton = () => {
  const { zoomMode, keyboardFocusMode } = useZoomState();
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const PAN_MODE = 'panning';
  const panButtonRef = useRef<HTMLButtonElement>();
  const tabIndex = useA11yToolbarTabIndex(PAN_MODE);
  const { pan } = useHistogramInteractions();
  const setState = useSetState();
  const intl = useIntl();
  const isPanEnabled = pan?.enabled;
  const shouldFocusButton = PAN_MODE === keyboardFocusMode;
  const { overlayRef } = useOverlaysEvents();

  useButtonKeyboardFocus(panButtonRef, shouldFocusButton, handleFocus);

  function handleFocus() {
    setState((prev) => ({
      ...prev,
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: undefined,
      },
    }));
  }

  /** Handles the zoom panning when a 'enter' keyboard event happens and it's not in panning mode.
   * @param event - A keyboard event param.
   */
  const handlePanningKeyboardMode = (event: KeyboardEvent) => {
    if (event.key === 'Enter') {
      handlePanningToolbarMode(true);
    }
  };

  /** Handles the zoom panning when clicked. */
  const handlePanningToolbarMode = (isKeyboardMode: boolean = false) => {
    setState((prev) => ({
      ...prev,
      overlays: {
        ...prev.overlays,
        visibleTooltip: false,
        pinnedTooltip: false,
      },
      zoom: {
        ...prev.zoom,
        zoomMode: PAN_MODE,
        activeKeyboardMode: isKeyboardMode ? PAN_MODE : undefined,
      },
    }));
  };

  useToolbarEvent<KeyboardEvent>(
    'keydown',
    () => handlePanningToolbarMode(true),
    isPan,
    isChartWithZoom,
    overlayRef?.current as HTMLDivElement,
  );

  return isPanEnabled ? (
    <ChartToolbarRenderer.Control
      ref={panButtonRef}
      prefixIcon={<PanHorizontalIcon />}
      tooltipText={intl.formatMessage(HISTOGRAM_MESSAGES.zoomModePan)}
      tooltipKeyShortcut="P"
      selected={zoomMode === PAN_MODE}
      onKeyDown={handlePanningKeyboardMode}
      onClick={() => handlePanningToolbarMode()}
      tabIndex={tabIndex}
      disabled={!isChartWithZoom}
    />
  ) : null;
};

PanButton['displayName'] = 'PanButton';
